window.EP = {"name": "ch7", "label": "एपिसोड 7", "en": "The CIA Left Something on Our Mountain", "duration": 1232.49, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 15.33, "text": "चैप्टर सेवन। द सी-आई-ए लेफ़्ट समथिंग ऑन आवर माउंटेन"}, {"start": 15.88, "end": 18.99, "text": "डे सेवन। जोशीमठ एंड औली"}], "captions": [{"start": 20.54, "end": 29.72, "text": "जोशीमठ पुलिस स्टेशन की खिड़की पर, एक टीन के डिब्बे में जीरेनियम का पौधा था, दो हज़ार चौबीस का एक कैलेंडर,", "who": "", "voice": "narrator", "diary": false}, {"start": 29.72, "end": 32.34, "text": "और बिष्ट नाम के एक इंस्पेक्टर,", "who": "", "voice": "narrator", "diary": false}, {"start": 32.34, "end": 36.98, "text": "जिन्होंने हमारी पूरी कहानी, एक बार भी टोके बिना सुनी।", "who": "", "voice": "narrator", "diary": false}, {"start": 37.43, "end": 40.47, "text": "जब मैंने ख़त्म किया, उन्होंने अपना फ़ोन उठाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 40.47, "end": 43.32, "text": "स्क्रॉल किया, और स्क्रीन मेरी तरफ़ घुमा दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 43.77, "end": 45.97, "text": "वो गोलू की वीडियो थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 45.97, "end": 49.84, "text": "रियल घोस्ट कॉट एट सवॉय, नॉट क्लिकबेट।", "who": "", "voice": "narrator", "diary": false}, {"start": 49.84, "end": 51.93, "text": "अब चालीस लाख व्यूज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 52.38, "end": 52.78, "text": "सर।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 52.98, "end": 55.3, "text": "इंस्पेक्टर बिष्ट ने मुझसे बड़े प्यार से कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 55.5, "end": 58.62, "text": "आप ही अननोन एंटिटी, फ़ीमेल, हो ना?", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 59.07, "end": 59.8, "text": "उनके पीछे,", "who": "", "voice": "narrator", "diary": false}, {"start": 59.8, "end": 63.94, "text": "दो कॉन्स्टेबल्स को अचानक छत पर कुछ बहुत दिलचस्प दिख गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 64.39, "end": 65.34, "text": "इंस्पेक्टर साहब…", "who": "", "voice": "narrator", "diary": false}, {"start": 65.79, "end": 68.5, "text": "एक हफ़्ते में भूत भी, और न्यूक्लियर बम भी।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 68.7, "end": 71.32, "text": "उन्होंने फ़ोन बहुत नरमी से नीचे रखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 71.52, "end": 73.78, "text": "सर, मैं आपकी इज़्ज़त करता हूँ।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 73.78, "end": 74.99, "text": "आप प्रोफ़ेसर हो।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 74.99, "end": 75.82, "text": "पर आप सोचो।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 75.82, "end": 83.22, "text": "मैं ये रिपोर्ट एस-पी साहब को भेजूँ: एक प्रोफ़ेसर ने एक ट्रेकिंग कंपनी के मालिक का नोटबुक उठा लिया,", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 83.22, "end": 87.45, "text": "और अब कहते हैं, कि वो सी-आई-ए का प्लूटोनियम ढूँढ रहा है।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 87.45, "end": 88.73, "text": "मैं क्या बताऊँगा?", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 88.73, "end": 90.77, "text": "कि सबूत है… एक पुराना गाना?", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 91.22, "end": 93.06, "text": "शाओनी डेस्क पर आगे झुकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 93.26, "end": 95.45, "text": "उसने मेरे भाई को किडनैप किया, सर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 95.9, "end": 97.72, "text": "और उन्हें चाय पिला के छोड़ दिया, मैडम।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 97.92, "end": 100.39, "text": "इंस्पेक्टर बिष्ट ने उसकी तरफ़ हाथ फैलाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 100.59, "end": 102.12, "text": "पैसे भी दिए ढाबे वाले को।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 102.12, "end": 103.03, "text": "मैं क्या लिखूँ?", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 103.03, "end": 104.68, "text": "किडनैपिंग विद हॉस्पिटैलिटी?", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 105.13, "end": 110.39, "text": "क्षितिज, जिसका हमेशा शुक्रगुज़ार रहूँगा, लगभग मुस्कुरा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 110.84, "end": 115.75, "text": "हम एक कंप्लेंट नंबर लेकर निकले, नोटबुक के एक्सचेंज के बारे में एक प्रिंटेड फ़ॉर्म,", "who": "", "voice": "narrator", "diary": false}, {"start": 115.75, "end": 119.63, "text": "और इंस्पेक्टर साहब की सच्ची सलाह, जो उन्होंने दरवाज़े पर मुझे दी,", "who": "", "voice": "narrator", "diary": false}, {"start": 119.63, "end": 121.96, "text": "कि जाकर औली से नंदा देवी का व्यू देखूँ:", "who": "", "voice": "narrator", "diary": false}, {"start": 122.16, "end": 123.95, "text": "वेदर अच्छा है आज, सर।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 123.95, "end": 125.14, "text": "भूत-वूत छोड़ो।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 125.14, "end": 126.08, "text": "पहाड़ देखो।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 127.58, "end": 131.65, "text": "गाड़ी में, शाओनी ने पुलिस का फ़ॉर्म अपने घुटने पर पलटा,", "who": "", "voice": "narrator", "diary": false}, {"start": 131.65, "end": 132.54, "text": "और पेन खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 132.99, "end": 133.45, "text": "ठीक है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 133.65, "end": 134.29, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 134.49, "end": 135.71, "text": "पुलिस नहीं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 135.71, "end": 136.81, "text": "तो… प्लान।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 137.26, "end": 141.98, "text": "उसने फ़ॉर्म के पीछे, साफ़-सुथरे नंबर्ड पॉइंट्स में, प्लान लिखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 141.98, "end": 144.46, "text": "क्योंकि ज़ाहिर है, उसने यही किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 144.46, "end": 147.08, "text": "और हर पॉइंट लिखते हुए ज़ोर से पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 147.53, "end": 147.8, "text": "एक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 147.8, "end": 149.42, "text": "पार्थ अकेला जाएगा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 149.42, "end": 151.85, "text": "रोहन को उसे अकेले देखना है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 152.3, "end": 152.56, "text": "दो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 152.56, "end": 155.34, "text": "पार्थ, रोहन की नोटबुक लौटा देगा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 155.34, "end": 158.56, "text": "हमारे पास हर पेज की फ़ोटो पहले से है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 158.56, "end": 160.3, "text": "रोहन को ये नहीं पता।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 160.75, "end": 161.09, "text": "तीन।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 161.09, "end": 164.0, "text": "रोहन को द्रोणागिरी वाला छंद चाहिए।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 164.0, "end": 165.72, "text": "हम उसे एक छंद देंगे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 165.72, "end": 167.01, "text": "असली वाला नहीं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 167.46, "end": 167.79, "text": "चार।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 167.79, "end": 171.14, "text": "पार्थ अपनी लाइव लोकेशन मुझसे शेयर करेगा,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 171.14, "end": 173.49, "text": "और फ़ोन पर सब रिकॉर्ड करेगा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 173.94, "end": 174.45, "text": "पाँच।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 174.45, "end": 178.04, "text": "अगर कुछ भी ग़लत हुआ, तो गब्बर भैया,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 178.04, "end": 183.67, "text": "शादी की बारात की तरह हॉर्न बजाते हुए, रोड पर ऊपर आएँगे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 184.12, "end": 185.0, "text": "नक़ली छंद?", "who": "", "voice": "narrator", "diary": false}, {"start": 185.2, "end": 186.0, "text": "मैंने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 186.45, "end": 188.1, "text": "उसने मुझे जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 188.1, "end": 189.83, "text": "वो अपने भाई की तरफ़ मुड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 190.03, "end": 190.72, "text": "क्षितिज।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 191.17, "end": 193.69, "text": "क्षितिज पहले से लिख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 193.69, "end": 198.45, "text": "वो बीस मिनट तक लिखता रहा, काटता रहा, फिर लिखता रहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 198.45, "end": 202.93, "text": "होंठों से शब्द बुदबुदाता, उँगलियों पर ताल गिनता,", "who": "", "voice": "narrator", "diary": false}, {"start": 202.93, "end": 205.26, "text": "जैसे बची राम जी गिनते थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 205.26, "end": 209.84, "text": "आख़िर में, उसने पेज फाड़ा, और मुझे दो लाइनें दीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 209.84, "end": 214.23, "text": "एक बूढ़े चरवाहे की लय की बहुत सधी हुई नक़ल में:", "who": "", "voice": "narrator", "diary": false}, {"start": 214.68, "end": 219.02, "text": "जहाँ मुर्दों की झील, हड्डियाँ गिन ले…", "who": "", "voice": "narrator", "diary": false}, {"start": 219.47, "end": 222.8, "text": "वहाँ नंदा की शिला, बर्फ़ में छीन ले…", "who": "", "voice": "narrator", "diary": false}, {"start": 223.25, "end": 226.85, "text": "एक रेड लाइट पर, गब्बर ने मेरे कंधे के ऊपर से पढ़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 226.85, "end": 229.94, "text": "और न चाहते हुए भी, इम्प्रेस होकर सीटी बजाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 230.14, "end": 231.03, "text": "रूपकुंड।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 231.03, "end": 232.7, "text": "मुर्दों की झील।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 232.9, "end": 234.98, "text": "उसने पेज की तरफ़ सिर हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 235.18, "end": 236.28, "text": "वो वहाँ जाएगा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 236.73, "end": 239.1, "text": "और हम कुमाऊँ जाएँगे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 239.3, "end": 240.16, "text": "शाओनी ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 240.36, "end": 241.63, "text": "राजुला के देस।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 242.08, "end": 244.26, "text": "मैंने दोनों लाइनें फिर से पढ़ीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 244.26, "end": 245.14, "text": "वो अच्छी थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 245.14, "end": 246.23, "text": "पुरानी लगती थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 246.23, "end": 247.12, "text": "सही लगती थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 247.57, "end": 248.26, "text": "क्षितिज।", "who": "", "voice": "narrator", "diary": false}, {"start": 248.46, "end": 249.98, "text": "मैंने उसकी तरफ़ मुड़ते हुए कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 250.18, "end": 252.6, "text": "तुम डायरी लिखते हो, क्लूज़ पकड़ते हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 252.6, "end": 254.56, "text": "और अब तुम लोक-गीत भी लिखते हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 254.56, "end": 257.37, "text": "मेरे पास सिर्फ़ एक लैपटॉप और आधी पीएचडी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 257.37, "end": 259.92, "text": "मुझे जेन्युइनली इनसिक्योरिटी हो रही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 260.37, "end": 262.54, "text": "आपके पास डेडपूल वाला मुँह भी है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 262.74, "end": 264.8, "text": "क्षितिज ने ऊपर देखे बिना मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 265.0, "end": 266.22, "text": "उसे बचा के रखो।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 266.22, "end": 267.6, "text": "आज ज़रूरत पड़ेगी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 269.1, "end": 273.73, "text": "औली की सड़क, जोशीमठ से लंबे-लंबे मोड़ों में ऊपर चढ़ती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 273.73, "end": 277.38, "text": "दरार वाली गलियों से होकर, ऐसे घरों के पास से,", "who": "", "voice": "narrator", "diary": false}, {"start": 277.38, "end": 280.05, "text": "जिनकी दीवारों पर तिरपाल पड़े हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 280.05, "end": 284.11, "text": "जोशीमठ धँस रहा है, उसके नीचे की ज़मीन खिसक रही है,", "who": "", "voice": "narrator", "diary": false}, {"start": 284.11, "end": 287.84, "text": "और शहर अपनी चिंता खुलेआम पहनता है, हर दरार पर।", "who": "", "voice": "narrator", "diary": false}, {"start": 287.84, "end": 292.38, "text": "पुराना रोपवे, जो कभी टूरिस्ट्स को स्लोप्स तक ले जाता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 292.38, "end": 293.68, "text": "सालों से बंद है।", "who": "", "voice": "narrator", "diary": false}, {"start": 293.68, "end": 296.51, "text": "गब्बर लंबे वाले रास्ते से, सड़क से,", "who": "", "voice": "narrator", "diary": false}, {"start": 296.51, "end": 299.59, "text": "गाड़ी चलाता रहा, और कोई कुछ नहीं बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 300.29, "end": 302.45, "text": "ऊपर पहुँचकर, दुनिया खुल गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 303.15, "end": 309.44, "text": "अक्टूबर के आख़िर में औली, एक बहुत बड़ा, ढलवाँ मैदान है, सुनहरा-भूरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 309.44, "end": 314.81, "text": "और पहली बर्फ़ से हल्का सा ढका हुआ, बाँज और देवदार से घिरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 314.81, "end": 319.62, "text": "और घाटी के उस पार, इतने पास, कि लगे पत्थर फेंक दोगे,", "who": "", "voice": "narrator", "diary": false}, {"start": 319.62, "end": 322.95, "text": "गढ़वाल हिमालय की पूरी दीवार खड़ी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 322.95, "end": 323.97, "text": "द्रोणागिरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 323.97, "end": 324.52, "text": "कामेट।", "who": "", "voice": "narrator", "diary": false}, {"start": 324.52, "end": 325.54, "text": "हाथी पर्वत।", "who": "", "voice": "narrator", "diary": false}, {"start": 326.24, "end": 327.5, "text": "और नंदा देवी।", "who": "", "voice": "narrator", "diary": false}, {"start": 328.2, "end": 333.06, "text": "मैंने उन्हें चंद्रशिला से सूर्यास्त के वक़्त देखा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 333.06, "end": 334.71, "text": "छोटी, और बहुत दूर।", "who": "", "voice": "narrator", "diary": false}, {"start": 334.71, "end": 339.85, "text": "यहाँ वो आधा आसमान भर रही थीं: दो चोटियाँ, सफ़ेद, नुकीली,", "who": "", "voice": "narrator", "diary": false}, {"start": 339.85, "end": 341.77, "text": "नामुमकिन रूप से ऊँची,", "who": "", "voice": "narrator", "diary": false}, {"start": 341.77, "end": 346.63, "text": "और चोटी से उड़ती बर्फ़ की एक पतली सी लकीर, जैसे साँस।", "who": "", "voice": "narrator", "diary": false}, {"start": 347.08, "end": 351.18, "text": "उनकी ढलानों पर कहीं, सोलह अक्टूबर उन्नीस सौ पैंसठ से,", "who": "", "voice": "narrator", "diary": false}, {"start": 351.18, "end": 354.12, "text": "प्लूटोनियम से भरा एक बक्सा… सो रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 354.57, "end": 355.8, "text": "मैंने हाथ जोड़े।", "who": "", "voice": "narrator", "diary": false}, {"start": 355.8, "end": 357.5, "text": "मैंने तय नहीं किया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 357.5, "end": 358.43, "text": "बस… जुड़ गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 359.93, "end": 365.35, "text": "स्लोप के ऊपर, एक चाय की दुकान के पास, जब मैं ग्यारह बजने का इंतज़ार कर रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 365.35, "end": 367.93, "text": "किसी ने कलछी से मेरी तरफ़ हाथ हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 368.38, "end": 368.74, "text": "महेश।", "who": "", "voice": "narrator", "diary": false}, {"start": 368.74, "end": 375.69, "text": "वो अपनी स्की-सीज़न वाली दुकान खोलने, जल्दी ऊपर आ गया था, और दुकान पहले से लोकल आदमियों से भरी थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 375.69, "end": 380.43, "text": "जो बहस कर रहे थे, जैसे हर जगह चाय की दुकानों पर आदमी बहस करते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 380.43, "end": 383.65, "text": "बस यहाँ वो एक देवी के बारे में बहस कर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 384.1, "end": 387.15, "text": "बारह साल में एक बार होती है राज जात।", "who": "", "voice": "local", "diary": false}, {"start": 387.35, "end": 389.99, "text": "उनमें से एक कह रहा था, गिलास पटकते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 390.19, "end": 391.84, "text": "और इस साल, दो-दो कमेटी!", "who": "", "voice": "local", "diary": false}, {"start": 391.84, "end": 394.72, "text": "कुरुड़ वाले सितंबर में होमकुंड तक ले गए।", "who": "", "voice": "local", "diary": false}, {"start": 394.72, "end": 399.18, "text": "नौटी वाले बोले, नहीं, हमारी राज जात दो हज़ार सत्ताईस में होगी…", "who": "", "voice": "local", "diary": false}, {"start": 399.63, "end": 402.45, "text": "तो माँ नंदा, दो बार ससुराल जाएँगी?", "who": "", "voice": "local", "diary": false}, {"start": 402.65, "end": 403.61, "text": "दूसरे ने पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 404.06, "end": 406.65, "text": "एक बार इस साल, एक बार अगले साल।", "who": "", "voice": "local", "diary": false}, {"start": 406.85, "end": 408.29, "text": "ज़ोर का ठहाका।", "who": "", "voice": "narrator", "diary": false}, {"start": 408.49, "end": 409.17, "text": "बेचारी।", "who": "", "voice": "local", "diary": false}, {"start": 409.62, "end": 413.48, "text": "गब्बर ने मेरे लिए समझाने को, पास झुककर बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 413.48, "end": 423.42, "text": "नंदा देवी राज जात: हर बारह साल में एक बार, देवी नंदा को उनके मायके से, उनके पति शिव के घर, कैलाश तक ले जाया जाता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 423.42, "end": 428.81, "text": "ऊँचे पहाड़ों में तीन हफ़्ते, दो सौ अस्सी किलोमीटर का पैदल सफ़र,", "who": "", "voice": "narrator", "diary": false}, {"start": 428.81, "end": 433.35, "text": "जिसके आगे-आगे चलता है, चार सींग वाला एक दुर्लभ मेढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 433.35, "end": 437.81, "text": "दो हज़ार छब्बीस में, दो कमेटियाँ राज़ी नहीं हो पाईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 437.81, "end": 439.95, "text": "एक सितंबर में आगे बढ़ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 439.95, "end": 442.52, "text": "दूसरी ने अगले साल तक टाल दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 442.52, "end": 446.12, "text": "एक महीने बाद भी, घाटी इस पर बहस कर रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 446.57, "end": 449.37, "text": "भगवान के घर में भी कमेटी की प्रॉब्लम।", "who": "", "voice": "narrator", "diary": false}, {"start": 449.57, "end": 451.25, "text": "मैंने पूरी दुकान से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 451.45, "end": 452.36, "text": "वेरी रिलेटेबल।", "who": "", "voice": "narrator", "diary": false}, {"start": 452.36, "end": 453.6, "text": "हमारे कॉलेज में भी।", "who": "", "voice": "narrator", "diary": false}, {"start": 454.05, "end": 456.51, "text": "महेश सबसे ज़्यादा ज़ोर से हँसा।", "who": "", "voice": "narrator", "diary": false}, {"start": 456.51, "end": 461.19, "text": "उसने बिना पूछे मेरी चाय फिर से भर दी, और उसकी आँखें मुझ पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 461.19, "end": 465.54, "text": "किसी चाय वाले की आँखों से, थोड़ी ज़्यादा देर टिकी रहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 465.99, "end": 467.28, "text": "मैंने नोटिस नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 467.28, "end": 468.22, "text": "क्षितिज ने किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 469.72, "end": 472.9, "text": "ठीक ग्यारह बजे, रोहन सहगल स्लोप के टॉप पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 472.9, "end": 477.31, "text": "एक लकड़ी की बेंच पर अकेला बैठा था, नंदा देवी को देखता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 477.76, "end": 478.98, "text": "कोई भल्ला नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 478.98, "end": 480.95, "text": "किसी तरह, वो और बुरा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 481.4, "end": 483.8, "text": "मैं बेंच के दूसरे किनारे पर बैठ गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 483.8, "end": 486.75, "text": "मेरा फ़ोन शर्ट की जेब में रिकॉर्ड कर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 486.75, "end": 489.43, "text": "मेरी लाइव लोकेशन शाओनी के पास जा रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 489.43, "end": 491.84, "text": "मेरे घुटने… टुकड़े-टुकड़े हो रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 492.29, "end": 493.74, "text": "ख़ूबसूरत हैं, है ना।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 493.94, "end": 495.78, "text": "रोहन ने मेरी तरफ़ देखे बिना कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 495.98, "end": 498.7, "text": "मैं उन्नीस साल की उम्र से यहाँ आ रहा हूँ।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 498.7, "end": 502.41, "text": "सैंक्चुअरी के लिए ट्रेक्स लीड करता था, बंद होने से पहले।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 502.41, "end": 505.26, "text": "आपको पता है, अस्सी के दशक में बंद कर दी थी?", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 505.26, "end": 506.98, "text": "ऑफ़िशियली, इकोलॉजी के लिए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 507.18, "end": 508.53, "text": "एक हल्की सी मुस्कान।", "who": "", "voice": "narrator", "diary": false}, {"start": 508.73, "end": 509.45, "text": "ऑफ़िशियली।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 509.9, "end": 512.14, "text": "मैंने अपनी तैयार की हुई स्पीच आज़माई।", "who": "", "voice": "narrator", "diary": false}, {"start": 512.34, "end": 516.39, "text": "आप जो ढूँढ रहे हो, अगर वो मिल गया, तो सिर्फ़ आपका नहीं…", "who": "", "voice": "narrator", "diary": false}, {"start": 516.84, "end": 522.0, "text": "… सिर्फ़ मेरा नहीं, सबका है, गंगा का, नीचे के करोड़ों लोगों का।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 522.0, "end": 523.88, "text": "मुझे पता है, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 523.88, "end": 528.47, "text": "मैंने वही आर्टिकल्स पढ़े हैं, जो आपने उस गाड़ी में पढ़े।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 528.67, "end": 535.3, "text": "अब वो मुड़ा, और मुझे देखा, और एक सेकंड के लिए उसका चार्म फिसल गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 535.3, "end": 538.92, "text": "और मैंने देखा, कि उसके नीचे क्या था।", "who": "", "voice": "narrator", "diary": false}, {"start": 538.92, "end": 540.13, "text": "पागलपन नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 540.13, "end": 541.84, "text": "उससे भी बुरा कुछ।", "who": "", "voice": "narrator", "diary": false}, {"start": 541.84, "end": 542.44, "text": "सुकून।", "who": "", "voice": "narrator", "diary": false}, {"start": 542.64, "end": 545.45, "text": "आपको पता है, उस डिवाइस का क्या होगा?", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 545.45, "end": 546.15, "text": "कुछ नहीं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 546.15, "end": 547.86, "text": "ग्लेशियर पिघलता रहेगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 547.86, "end": 552.7, "text": "एक दिन कोई ट्रेकर, या कोई बकरी, या कोई बाढ़, उसे नीचे ले आएगी।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 552.7, "end": 553.79, "text": "किसी गाँव में।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 553.79, "end": 554.8, "text": "किसी नदी में।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 554.8, "end": 556.59, "text": "और कोई तैयार नहीं होगा,", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 556.59, "end": 560.49, "text": "क्योंकि कोई याद ही नहीं रखना चाहता, कि वो वहाँ है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 560.69, "end": 561.72, "text": "उसने कंधे उचकाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.92, "end": 564.92, "text": "मैं बस वो हूँ, जो तैयार है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 565.37, "end": 566.33, "text": "बेचने के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 566.53, "end": 567.08, "text": "मैंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 567.53, "end": 568.48, "text": "ढूँढने के लिए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 568.48, "end": 569.97, "text": "उसके बाद क्या होता है…", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 570.17, "end": 571.53, "text": "उसने हाथ फैलाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 571.73, "end": 572.78, "text": "… वो इकोनॉमिक्स है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 573.23, "end": 577.56, "text": "उसने हमारे बीच बेंच से एक चीड़ का फल उठाया, और उसे वापस रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 577.56, "end": 580.67, "text": "सावधानी से, लकड़ी के किनारे से एकदम पैरेलल।", "who": "", "voice": "narrator", "diary": false}, {"start": 580.67, "end": 583.05, "text": "फिर उसे एक मिलीमीटर और सीधा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 583.05, "end": 587.02, "text": "मैंने उसे सवॉय में मेरी नोटबुक के साथ ऐसा करते देखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 587.02, "end": 590.35, "text": "बाद में मुझे पता चलना था, कि वो ये तब करता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 590.35, "end": 592.37, "text": "जब वो हिसाब लगा रहा होता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 592.82, "end": 596.42, "text": "मैंने उन्हें पहली बार उन्नीस साल की उम्र में देखा था।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 596.62, "end": 599.58, "text": "उसने पहाड़ की तरफ़ सिर हिलाते हुए कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 599.58, "end": 602.7, "text": "और एक पल के लिए उसकी आवाज़ लगभग जवान थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 602.9, "end": 604.36, "text": "ऐसी ही एक पहाड़ी से।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 604.36, "end": 608.29, "text": "मैं तीन दोस्तों, एक टेंट, और बिना पैसों के ऊपर आया था।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 608.29, "end": 610.4, "text": "अँधेरा होने तक वहीं बैठा रहा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 610.4, "end": 612.01, "text": "उसी दिन मैंने तय किया,", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 612.01, "end": 615.8, "text": "कि अपनी ज़िंदगी लोगों को उन तक ले जाने में बिताऊँगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 616.0, "end": 618.48, "text": "वो मुस्कुराया, बिना गर्माहट के।", "who": "", "voice": "narrator", "diary": false}, {"start": 618.68, "end": 621.18, "text": "फिर उन्होंने सैंक्चुअरी बंद कर दी।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 621.18, "end": 622.81, "text": "फिर परमिट्स बंद हो गए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 622.81, "end": 626.27, "text": "फिर एक बाढ़, एक पैंडेमिक, एक शहर, जो धँसने लगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 626.27, "end": 631.14, "text": "आपको पता है, प्रोफ़ेसर, कैसा लगता है… किसी ऐसी चीज़ से प्यार करना,", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 631.14, "end": 634.24, "text": "जो बार-बार आपके मुँह पर दरवाज़ा बंद कर दे?", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 634.94, "end": 636.36, "text": "उसने मुझे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 637.06, "end": 640.57, "text": "समिट सीक्रेट्स पर ग्यारह करोड़ का क़र्ज़ है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 640.57, "end": 643.52, "text": "मेरे इन्वेस्टर्स अपने पैसे चाहते हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 643.52, "end": 648.38, "text": "और उस पहाड़ पर एक बक्सा है, जिसे बाहर के कुछ बहुत सीरियस लोग,", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 648.38, "end": 651.57, "text": "अपने हाथ में रखने के लिए बहुत कुछ देंगे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 651.77, "end": 653.29, "text": "उसने फिर कंधे उचकाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 653.49, "end": 656.17, "text": "पहाड़ पर मेरी एक चाबी… उधार है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 656.62, "end": 660.54, "text": "मैं चाहूँगा कि आपसे कहूँ, मेरे पास कोई शानदार जवाब था।", "who": "", "voice": "narrator", "diary": false}, {"start": 660.54, "end": 665.63, "text": "मेरे पास था वो डेडपूल वाला मुँह, जिसे क्षितिज ने बचाकर रखने को कहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 665.63, "end": 668.03, "text": "और मैं पूरी सुबह उसे बचाए हुए था।", "who": "", "voice": "narrator", "diary": false}, {"start": 668.03, "end": 670.0, "text": "तो मैंने उसे इस्तेमाल किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 670.45, "end": 671.09, "text": "रोहन।", "who": "", "voice": "narrator", "diary": false}, {"start": 671.29, "end": 672.07, "text": "मैंने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 672.27, "end": 673.32, "text": "मैं प्रोफ़ेसर हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 673.32, "end": 676.35, "text": "मैंने तीन सौ स्टूडेंट्स को एक साथ वाइवा में देखा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 676.35, "end": 678.91, "text": "उनमें से कई लोग आपसे ज़्यादा कॉन्फ़िडेंट थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 679.11, "end": 679.91, "text": "मैं रुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 680.11, "end": 681.94, "text": "… और सब फ़ेल हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 682.39, "end": 683.11, "text": "वो हँसा।", "who": "", "voice": "narrator", "diary": false}, {"start": 683.11, "end": 683.73, "text": "सच में।", "who": "", "voice": "narrator", "diary": false}, {"start": 683.73, "end": 686.42, "text": "उसने मेरे कंधे पर ऐसे थपकी दी,", "who": "", "voice": "narrator", "diary": false}, {"start": 686.42, "end": 689.91, "text": "जैसे हमने अभी-अभी एक अच्छा लंच किया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 690.36, "end": 691.73, "text": "नोटबुक, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 692.18, "end": 694.15, "text": "मैंने उसे उसकी नोटबुक दे दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 694.15, "end": 698.44, "text": "उसने जल्दी से पन्ने पलटे, फ़ोटो और कोऑर्डिनेट्स चेक करते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 698.44, "end": 700.34, "text": "फिर उसने दोबारा हाथ बढ़ाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 700.79, "end": 703.34, "text": "मैंने उसे क्षितिज की दो लाइनें दीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 703.34, "end": 707.35, "text": "अपने फ़ोन नोट्स से एक पेज पर, अपनी लिखावट में लिखी हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 707.8, "end": 709.5, "text": "उसने उन्हें एक बार पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 709.5, "end": 710.0, "text": "दो बार।", "who": "", "voice": "narrator", "diary": false}, {"start": 710.0, "end": 712.57, "text": "उसकी आँखें, बहुत हल्के से, चमक उठीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 713.02, "end": 714.63, "text": "मुर्दों की झील।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 714.83, "end": 715.7, "text": "वो बुदबुदाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 715.9, "end": 716.59, "text": "रूपकुंड।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 716.59, "end": 717.45, "text": "ऑफ़ कोर्स।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 717.45, "end": 718.75, "text": "राज जात का रूट।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 718.75, "end": 721.51, "text": "चरवाहों का गर्मियों वाला रास्ता।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 721.71, "end": 726.11, "text": "उसने पेज को सावधानी से मोड़कर, अपनी अंदर वाली जेब में रख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 726.31, "end": 727.05, "text": "थैंक यू।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 727.05, "end": 727.69, "text": "सच में।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 728.14, "end": 730.83, "text": "फिर उसने अपनी जैकेट में हाथ डाला,", "who": "", "voice": "narrator", "diary": false}, {"start": 730.83, "end": 733.45, "text": "और मुझे मेरी अपनी नोटबुक थमा दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 733.45, "end": 734.68, "text": "सर, लिखते रहना।", "who": "", "voice": "narrator", "diary": false}, {"start": 734.68, "end": 735.9, "text": "मैंने उसे खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 735.9, "end": 737.13, "text": "सब कुछ वहाँ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 737.58, "end": 742.09, "text": "सिवाय एक पेज के, जो स्पाइन से सफ़ाई से फाड़ा गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 742.09, "end": 744.86, "text": "वो पेज, जिस पर मम्मी का नंबर था।", "who": "", "voice": "narrator", "diary": false}, {"start": 745.31, "end": 746.12, "text": "इंश्योरेंस।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 746.32, "end": 748.16, "text": "रोहन ने खड़े होते हुए बड़े प्यार से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 748.36, "end": 752.43, "text": "बस तब तक, जब तक मैं आपकी छोटी सी कविता चेक नहीं कर लेता।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 752.63, "end": 755.23, "text": "उसने एक बार और नंदा देवी की तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 755.43, "end": 758.57, "text": "आपको पता है, मैं एक पोर्टर के साथ काम करता था।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 758.57, "end": 759.31, "text": "जवान लड़का।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 759.31, "end": 760.47, "text": "बर्फ़ पर कमाल का।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 760.47, "end": 762.31, "text": "उसे भी पुराने गाने पसंद थे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 762.31, "end": 764.42, "text": "हर वक़्त उन्हीं की बात करता था।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 764.62, "end": 766.38, "text": "सिर का एक हल्का सा झटका।", "who": "", "voice": "narrator", "diary": false}, {"start": 766.58, "end": 770.77, "text": "गाने, प्यार करने के लिए ख़तरनाक चीज़ें होते हैं, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 770.77, "end": 773.26, "text": "उन गाँवों में किसी से भी पूछ लीजिए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 773.71, "end": 777.22, "text": "वो मैदान के उस पार, सड़क की तरफ़ चला गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 777.22, "end": 782.01, "text": "बर्फ़ के सामने एक महँगी जैकेट, और पीछे मुड़कर नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 782.46, "end": 788.05, "text": "मैं बहुत देर तक उस बेंच पर बैठा रहा, गोद में अपनी नोटबुक,", "who": "", "voice": "narrator", "diary": false}, {"start": 788.05, "end": 792.06, "text": "और उसमें एक छेद, जहाँ एक पेज हुआ करता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 793.56, "end": 795.79, "text": "तभी हमें भिनभिनाहट सुनाई दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 796.49, "end": 801.47, "text": "गोलू, सौ मीटर दूर, स्लोप के किनारे खड़ा, एक ड्रोन उड़ा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 801.47, "end": 805.26, "text": "उसने पूरी सुबह हममें से किसी से बात नहीं की थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 805.26, "end": 810.08, "text": "द्रोणागिरी के बाद, गौरव के बाद, वो दूर-दूर रहा था: रूठा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 810.08, "end": 813.3, "text": "क्षितिज को लगा; छिपता हुआ, शाओनी को लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 813.3, "end": 819.26, "text": "अब उसका ड्रोन मैदान के ऊपर बहुत ऊँचा था, और मुझे एक झटके के साथ एहसास हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 819.26, "end": 823.52, "text": "कि वो शायद पूरे वक़्त, रोहन और मुझे फ़िल्म कर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 823.97, "end": 826.99, "text": "मैं खड़ा हुआ, और बर्फ़ के उस पार उस पर चिल्लाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 827.19, "end": 827.6, "text": "गोलू!", "who": "", "voice": "narrator", "diary": false}, {"start": 827.6, "end": 827.93, "text": "भाई!", "who": "", "voice": "narrator", "diary": false}, {"start": 827.93, "end": 828.75, "text": "डिलीट करो!", "who": "", "voice": "narrator", "diary": false}, {"start": 828.75, "end": 829.9, "text": "वो रिकॉर्डिंग…", "who": "", "voice": "narrator", "diary": false}, {"start": 830.35, "end": 836.82, "text": "ड्रोन ऊपर चढ़ा, मुड़ा, और ट्रीलाइन के ऊपर की ढलान की तरफ़ बहता चला गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 836.82, "end": 840.2, "text": "औली के पीछे पहाड़ियों की एक तह की ओर,", "who": "", "voice": "narrator", "diary": false}, {"start": 840.2, "end": 842.67, "text": "जहाँ बर्फ़ ज़्यादा मोटी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 843.12, "end": 845.8, "text": "फिर उसकी भिनभिनाहट बंद हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 846.25, "end": 850.2, "text": "वो एक ख़ूबसूरत, ख़ामोश सेकंड के लिए हवा में टँगा रहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 850.2, "end": 852.36, "text": "किसी कार्टून कैरेक्टर की तरह,", "who": "", "voice": "narrator", "diary": false}, {"start": 852.36, "end": 855.12, "text": "जो अभी-अभी चट्टान से आगे दौड़ गया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 855.12, "end": 858.4, "text": "फिर वो सीधा बर्फ़ में गिरा… और ग़ायब हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 858.85, "end": 861.01, "text": "गोलू ने उसके पीछे घूरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 861.21, "end": 861.76, "text": "बैटरी।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 861.96, "end": 863.7, "text": "उसने किसी से नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 863.9, "end": 865.27, "text": "ठंड में बैटरी मर गई।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 865.72, "end": 866.99, "text": "मैं रीडर की तरफ़ मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 866.99, "end": 868.72, "text": "मैं अभी आपकी तरफ़ मुड़ रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 869.17, "end": 870.28, "text": "एक और डिवाइस।", "who": "", "voice": "narrator", "diary": false}, {"start": 870.48, "end": 871.27, "text": "मैंने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 871.47, "end": 873.07, "text": "नंदा देवी पर खो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 873.07, "end": 874.99, "text": "ये बेसिकली एक परंपरा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 876.49, "end": 880.13, "text": "क्षितिज ने ज़िद की, कि हम उसे खोदकर निकालें।", "who": "", "voice": "narrator", "diary": false}, {"start": 880.13, "end": 884.18, "text": "उसने ये हम सबसे कहा, लेकिन वो गोलू को देख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 884.63, "end": 885.14, "text": "फ़ुटेज।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 885.14, "end": 885.5, "text": "डेटा।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 885.5, "end": 887.25, "text": "कुछ भी हो सकता है उसमें।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 887.7, "end": 888.91, "text": "चालीस मिनट लगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 888.91, "end": 894.87, "text": "गोलू सबसे आगे गया, मैदान के पीछे की ढलान पर घुटनों तक बर्फ़ में धँसता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 894.87, "end": 897.37, "text": "उसके पीछे शाओनी, उसके पीछे मैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 897.37, "end": 901.32, "text": "हाँफते हुए इस चैप्टर के राइटर की शिकायत करता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 901.32, "end": 903.33, "text": "आख़िरकार हमें ड्रोन मिला,", "who": "", "voice": "narrator", "diary": false}, {"start": 903.33, "end": 907.28, "text": "एक पहाड़ी पर बर्फ़ के ढेर में नाक के बल धँसा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 907.28, "end": 908.65, "text": "पत्थर जितना ठंडा।", "who": "", "voice": "narrator", "diary": false}, {"start": 909.1, "end": 912.38, "text": "गोलू हमें फ़ुटेज नहीं दिखाना चाहता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 912.38, "end": 914.1, "text": "वो पहली अजीब बात थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 914.1, "end": 917.46, "text": "उसने ड्रोन को सीने से लगाए रखा, और कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 917.46, "end": 920.39, "text": "कि मेमोरी कार्ड शायद टूट गया होगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 920.39, "end": 924.09, "text": "शाओनी ने बस अपना हाथ आगे बढ़ाया, हथेली ऊपर,", "who": "", "voice": "narrator", "diary": false}, {"start": 924.09, "end": 929.0, "text": "और तब तक इंतज़ार किया, जब तक उसने कार्ड उसे दे नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 929.45, "end": 932.56, "text": "हमने उसे बसंती के पिछले हिस्से में,", "who": "", "voice": "narrator", "diary": false}, {"start": 932.56, "end": 936.01, "text": "गरजते हीटर के साथ, मेरे लैपटॉप पर देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 936.46, "end": 936.96, "text": "मैदान।", "who": "", "voice": "narrator", "diary": false}, {"start": 936.96, "end": 937.37, "text": "बेंच।", "who": "", "voice": "narrator", "diary": false}, {"start": 937.37, "end": 939.75, "text": "रोहन और मैं, दो छोटे से आकार।", "who": "", "voice": "narrator", "diary": false}, {"start": 939.75, "end": 950.93, "text": "फिर ड्रोन ऊपर चढ़ता है, मुड़ता है, बहता नहीं, मैंने अब नोटिस किया, बल्कि आराम से, एकदम सटीक मुड़ता है, जैसे किसी रूट को फ़ॉलो कर रहा हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 950.93, "end": 954.71, "text": "और औली के पीछे की पहाड़ी के ऊपर से फिसलता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 954.71, "end": 958.58, "text": "पहाड़ियों में एक छिपे हुए गड्ढे में पहुँचता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 958.58, "end": 961.29, "text": "जो स्लोप से कभी दिख ही नहीं सकता।", "who": "", "voice": "narrator", "diary": false}, {"start": 961.99, "end": 964.45, "text": "और उस गड्ढे में: टेंट्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 965.15, "end": 968.21, "text": "चार बड़े, नारंगी एक्सपीडिशन टेंट्स,", "who": "", "voice": "narrator", "diary": false}, {"start": 968.21, "end": 971.79, "text": "उस तरह के, जो मेरी कार से महँगे होते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 971.79, "end": 972.57, "text": "रस्सियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 972.57, "end": 975.19, "text": "एक चट्टान से टिकी आइस-एक्सेज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 975.19, "end": 977.37, "text": "दो आदमी स्लेज लाद रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 977.37, "end": 982.7, "text": "पहियों पर एक मशीन, जो लॉनमोवर और रडार के मेल जैसी दिख रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 982.7, "end": 984.97, "text": "ग्राउंड-पेनिट्रेटिंग रडार,", "who": "", "voice": "narrator", "diary": false}, {"start": 984.97, "end": 989.33, "text": "क्षितिज ने कहा; उसने एक डॉक्यूमेंट्री में देखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 989.33, "end": 995.79, "text": "और, दो आदमियों के बीच, सावधानी से सबसे बड़े टेंट की तरफ़ ले जाया जाता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 995.79, "end": 998.06, "text": "एक भारी, ग्रे धातु का केस।", "who": "", "voice": "narrator", "diary": false}, {"start": 998.51, "end": 1001.92, "text": "ड्रोन बैटरी मरने से ठीक पहले नीचे झुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 1001.92, "end": 1006.02, "text": "तीन फ़्रेम्स के लिए, केस ने पूरी स्क्रीन भर दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1006.47, "end": 1010.47, "text": "उसकी साइड पर पीले रंग में, स्टेंसिल से बना एक सिम्बल था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1010.47, "end": 1012.82, "text": "जिसे धरती का हर इंसान पहचानता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 1012.82, "end": 1015.25, "text": "भले ही उसे पता न हो कि पहचानता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1015.7, "end": 1019.14, "text": "एक काले बिंदु के चारों तरफ़, तीन काली पंखुड़ियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1019.84, "end": 1020.95, "text": "रेडिएशन।", "who": "", "voice": "narrator", "diary": false}, {"start": 1021.65, "end": 1023.57, "text": "गाड़ी में किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1024.02, "end": 1029.29, "text": "और फिर, इस पूरी ट्रिप पर पहली बार, मेरी डे-जॉब काम आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1029.74, "end": 1032.24, "text": "क्योंकि ड्रोन सिर्फ़ वीडियो नहीं रखता।", "who": "", "voice": "narrator", "diary": false}, {"start": 1032.24, "end": 1034.87, "text": "उस मेमोरी कार्ड पर हर क्लिप के बग़ल में,", "who": "", "voice": "narrator", "diary": false}, {"start": 1034.87, "end": 1038.09, "text": "एक छोटी सी, बोरिंग टेक्स्ट फ़ाइल थी: फ़्लाइट लॉग।", "who": "", "voice": "narrator", "diary": false}, {"start": 1038.09, "end": 1042.16, "text": "फ़्लाइट का हर सेकंड वहाँ लिखा होता है: लैटिट्यूड, लॉन्गिट्यूड,", "who": "", "voice": "narrator", "diary": false}, {"start": 1042.16, "end": 1045.84, "text": "ऊँचाई, स्पीड, बैटरी, और वो मोड, जिसमें ड्रोन उड़ रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1045.84, "end": 1047.74, "text": "उन फ़ाइलों को कोई नहीं देखता।", "who": "", "voice": "narrator", "diary": false}, {"start": 1047.74, "end": 1048.73, "text": "मैं डेवलपर हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1048.73, "end": 1051.42, "text": "मैं बोरिंग फ़ाइलें मज़े के लिए देखता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1051.87, "end": 1059.02, "text": "मैंने उसे एक कोड एडिटर में खोला, अभी भी जमी हुई उँगलियों से पाइथन की चार लाइनें लिखीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 1059.02, "end": 1062.27, "text": "और फ़्लाइट पाथ को एक मैप पर प्लॉट किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1062.72, "end": 1064.19, "text": "वो बहना नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1064.19, "end": 1069.91, "text": "वो मैदान से गड्ढे तक एक सीधी लाइन थी, फिर कैंप के ऊपर एक साफ़,", "who": "", "voice": "narrator", "diary": false}, {"start": 1069.91, "end": 1074.7, "text": "कसा हुआ आयत, एक सर्वे पैटर्न, फिर वापस एक सीधी लाइन।", "who": "", "voice": "narrator", "diary": false}, {"start": 1074.7, "end": 1079.68, "text": "और मोड वाले कॉलम में, टेक-ऑफ़ के बाद पहले ही सेकंड से,", "who": "", "voice": "narrator", "diary": false}, {"start": 1079.68, "end": 1083.18, "text": "एक ही शब्द, ग्यारह सौ बार दोहराया हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1083.88, "end": 1084.6, "text": "वेपॉइंट।", "who": "", "voice": "narrator", "diary": false}, {"start": 1085.3, "end": 1087.06, "text": "ये ड्रोन ख़ुद नहीं गया वहाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1087.26, "end": 1087.94, "text": "मैंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1087.94, "end": 1089.66, "text": "मेरी आवाज़ बहुत छोटी लगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1089.86, "end": 1091.5, "text": "इसका रूट पहले से सेट था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1091.5, "end": 1092.87, "text": "घर पे बैठके, मैप पे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1092.87, "end": 1096.58, "text": "किसी को पता था कैंप कहाँ है… और उसने इसे वहाँ भेजा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1097.03, "end": 1099.59, "text": "क्षितिज मेरे कंधे के ऊपर से झुका,", "who": "", "voice": "narrator", "diary": false}, {"start": 1099.59, "end": 1102.7, "text": "स्क्रीन पढ़ी, और हर कोऑर्डिनेट लिख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1102.7, "end": 1105.89, "text": "फिर उसने मुझे ऐसे एक्सप्रेशन के साथ देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1105.89, "end": 1108.77, "text": "जिसे मैं पूरी ज़िंदगी सँभालकर रखूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1109.22, "end": 1109.76, "text": "भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 1109.96, "end": 1110.6, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1110.8, "end": 1112.18, "text": "आज आपने नोट्स बनाए।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 1112.63, "end": 1116.31, "text": "फिर हम चारों, एक ही पल में, गोलू की तरफ़ देखने को मुड़े।", "who": "", "voice": "narrator", "diary": false}, {"start": 1116.76, "end": 1119.72, "text": "लेकिन गोलू अब गाड़ी के बाहर खड़ा नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1120.17, "end": 1121.74, "text": "उसकी सफ़ेद एस-यू-वी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1121.74, "end": 1125.97, "text": "पहले ही जोशीमठ की सड़क पर आधे रास्ते तक पहुँच चुकी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1126.42, "end": 1128.54, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1128.54, "end": 1130.97, "text": "डे सेवन, जोशीमठ और औली।", "who": "", "voice": "narrator", "diary": true}, {"start": 1131.42, "end": 1132.84, "text": "पुलिस मदद नहीं करेगी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1132.84, "end": 1135.83, "text": "इंस्पेक्टर बिष्ट गोलू की वीडियोज़ देखते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1135.83, "end": 1137.86, "text": "सब गोलू की वीडियोज़ देखते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1138.31, "end": 1140.09, "text": "आर. ने नक़ली छंद ले लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1140.09, "end": 1141.59, "text": "वो रूपकुंड जा रहा है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1141.59, "end": 1142.02, "text": "अच्छा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1142.02, "end": 1145.45, "text": "उसने इंश्योरेंस के लिए मम्मी वाला पेज फाड़ लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1145.45, "end": 1145.81, "text": "बुरा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1146.26, "end": 1149.27, "text": "आर. ने एक जवान पोर्टर के बारे में बात की,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1149.27, "end": 1152.43, "text": "बर्फ़ पर कमाल का, जिसे पुराने गाने पसंद थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1152.43, "end": 1153.24, "text": "पास्ट टेंस।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1153.24, "end": 1153.53, "text": "कौन?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1153.98, "end": 1157.56, "text": "आर. की कंपनी पर ग्यारह करोड़ का क़र्ज़ है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1157.56, "end": 1160.11, "text": "पहाड़ पर मेरी एक चाबी उधार है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1160.11, "end": 1162.67, "text": "उसने पहले पहाड़ से प्यार किया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1162.67, "end": 1164.71, "text": "फिर उसे अपना बनाना चाहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1164.71, "end": 1166.33, "text": "फिर उसे बेचना चाहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1166.33, "end": 1169.99, "text": "सोचते वक़्त वो चीज़ों को लाइन में लगाता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1169.99, "end": 1170.93, "text": "चीड़ का फल।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1170.93, "end": 1171.52, "text": "नोटबुक।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1171.52, "end": 1174.33, "text": "जैसे कोई कुछ डिफ़्यूज़ कर रहा हो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1174.78, "end": 1178.38, "text": "आर. का कैंप, औली के ऊपर एक छिपे गड्ढे में है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1178.38, "end": 1183.42, "text": "एक्सपीडिशन टेंट्स, ग्राउंड रडार, और रेडिएशन सिम्बल वाला एक केस।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1183.42, "end": 1185.58, "text": "वो अब अंदाज़े नहीं लगा रहे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1185.58, "end": 1187.42, "text": "वो पूरी तैयारी में हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1187.87, "end": 1191.49, "text": "पार्थ भाई ने पाइथन से ड्रोन का फ़्लाइट लॉग पढ़ा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1191.49, "end": 1193.37, "text": "ग्यारह सौ सेकंड, वेपॉइंट।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1193.37, "end": 1198.2, "text": "गोलू का ड्रोन, पहले से सेट रूट पर, सीधा आर. के कैंप के ऊपर उड़ा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1198.2, "end": 1202.05, "text": "या तो गोलू आर. के लिए काम करता है, और गड़बड़ कर दी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1202.05, "end": 1206.73, "text": "या उसे पता था कि कैंप कहाँ है, और वो चाहता था कि हम उसे देखें।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1206.73, "end": 1211.4, "text": "दीदी: अगर वो रोहन के लिए काम करता है, तो हमें ये क्यों दिखाया?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1211.4, "end": 1212.23, "text": "अच्छा सवाल।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1212.23, "end": 1213.59, "text": "फिर वो भागा क्यों?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1214.04, "end": 1217.99, "text": "महेश ने बिना पूछे पार्थ भाई की चाय फिर से भरी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1217.99, "end": 1220.65, "text": "और पूरे वक़्त उन्हें देखता रहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1220.65, "end": 1221.86, "text": "शायद कुछ नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1221.86, "end": 1223.49, "text": "फिर भी लिख रहा हूँ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 19.34, "bed": "police"}, {"at": 126.38, "bed": "plan"}, {"at": 267.9, "bed": "sinking"}, {"at": 299.09, "bed": "auli"}, {"at": 358.73, "bed": "stall"}, {"at": 468.52, "bed": "bench"}, {"at": 792.36, "bed": "drone"}, {"at": 875.29, "bed": "trek"}, {"at": 928.25, "bed": "hollow"}, {"at": 1022.82, "bed": "code"}, {"at": 1125.22, "bed": "diary"}, {"at": 1125.22, "bed": "diary"}], "hits": [{"at": 191.02, "fx": "page"}, {"at": 214.53, "fx": "flute"}, {"at": 346.93, "fx": "sting"}, {"at": 737.43, "fx": "sting"}, {"at": 793.41, "fx": "drone"}, {"at": 842.97, "fx": "dronefall"}, {"at": 869.02, "fx": "sting_light"}, {"at": 1019.69, "fx": "sting"}, {"at": 1051.72, "fx": "typing"}, {"at": 1083.73, "fx": "sting"}, {"at": 1116.61, "fx": "carstart"}, {"at": 1120.02, "fx": "sting"}, {"at": 1213.89, "fx": "sting"}], "next": {"label": "एपिसोड 8", "en": "Who Brought the Greeks to Skeleton Lake?", "hook": "मुर्दों की झील। बर्फ़ में हड्डियाँ। और एक सवाल: ग्रीक लोग यहाँ क्या कर रहे थे?"}};
